  /* ---------------- Google Business Profile ---------------- */
  const GBP_HELP=`<h3>Google Business Profile — Setup, Posts + Maps Reviews</h3><p class="uc-help-lead">Use one Google OAuth connection to discover Business Profile accounts/locations, publish new Fitness Tips as Business Profile local posts, and load/reply to Google Maps reviews for the selected location.</p><div class="uc-warning"><strong>Important — OAuth Connected ≠ Business Profile API Approved.</strong> Seeing your Google email only confirms OAuth. Google separately approves Business Profile API access at the <strong>Google Cloud project</strong> level. If Load Accounts & Locations returns HTTP 429 and the project quota is 0, request Basic API Access for that same project; changing the Client ID or reconnecting will not fix quota 0.</div><ol><li>Open <a href="https://developers.google.com/my-business/content/prereqs" target="_blank" rel="noopener">Google Business Profile API prerequisites</a> and confirm the Google account you use is an owner/manager of an active verified Business Profile.</li><li>In the Google Cloud project that owns this OAuth Client ID, submit the <strong>Application for Basic API Access</strong> if Business Profile API quota is 0. Google states quota 0 means the project has not yet been approved.</li><li>After approval, follow <a href="https://developers.google.com/my-business/content/basic-setup" target="_blank" rel="noopener">Google's Basic setup</a> and enable the Business Profile APIs in the same project. For this card, account discovery uses <strong>My Business Account Management API</strong>, location discovery uses <strong>My Business Business Information API</strong>, and Posts/Reviews use <strong>Google My Business API</strong>.</li><li>Create/reuse a Google OAuth 2.0 <strong>Web application</strong> and add the OAuth Redirect URL shown on this card as an Authorized redirect URI.</li><li>Save the Client ID and Client Secret, click <strong>Connect Google Business Profile</strong>, choose the Google account that manages the location, and approve <strong>business.manage</strong>.</li><li>Click <strong>Load Accounts & Locations</strong>. Choose the correct account and verified location, then click <strong>Save Settings</strong>.</li><li>Click <strong>Test Connection</strong>. A full pass verifies live local-Post and review reads for the selected location. Only then enable automatic publishing.</li></ol><div class="uc-example"><strong>What the screenshot means:</strong> enabling <em>My Business Account Management API</em> is correct, but it is only part of the setup. If Google returns 429 before accounts can load, check the API quota/approval first. Your five Business Profiles being visible in Google Search proves the Google account manages them, but it does not by itself grant this Cloud project API access.</div><div class="uc-example"><strong>Supported in this dashboard after approval:</strong> create Business Profile local posts; list Google Maps reviews; reply to a review; and show those reviews in the Comments workspace. Google Business Profile does not expose a general visitor-like/comment moderation API for local Posts, so the dashboard does not invent unsupported Like/Delete controls.</div><div class="uc-warning"><strong>Google controls display.</strong> A successful API post can appear in Google Search/Maps according to Google's product rules. A separate Google Maps API key is not required for Business Profile posting or review replies; the Maps & Reviews section remains separate for embeds/place presentation.</div>`;
  function makeGoogleBusinessCard(){
    const d=document.createElement('details');d.className='card pay-detail uc-social-card uc-v167-api-card uc-v1611-google-business';d.dataset.socialCard='googleBusiness';
    d.innerHTML=`<summary>Google Business Profile</summary><form class="form" onsubmit="saveUCV1611GoogleBusiness(event)"><div class="uc-social-toggle-item"><label class="uc-social-toggle-capsule"><span class="switch"><input name="enabled" type="checkbox"><span class="slider"></span></span><strong>Enable Google Business Profile</strong></label><small class="uc-social-toggle-helper">Business Profile local posts + Google Maps review replies</small></div><div class="uc-social-info"><strong>Use:</strong> Publish new Fitness Tips as Business Profile updates and manage supported Google Maps review replies from Comments.</div><div class="uc-social-toggle-item"><label class="uc-social-toggle-capsule"><span class="switch"><input name="autoPublish" type="checkbox"><span class="slider"></span></span><strong>Automatically publish new Fitness Tips</strong></label><small class="uc-social-toggle-helper">Creates one Business Profile local post after a new Fitness Tip is published</small></div><div class="row"><div class="field"><label>OAuth Client ID</label><input name="clientId" placeholder="Google OAuth Client ID"><small class="hint">Web application OAuth client in Google Cloud.</small></div><div class="field"><label>OAuth Client Secret <small id="ucV1611GoogleBusinessSecretHint" class="hint inline-hint"></small></label><input name="clientSecret" type="password" placeholder="Leave blank to keep saved secret"><small class="hint">Stored in website settings. Do not place this value in public code.</small></div></div><span class="uc-social-webhook-label">OAuth Redirect URL</span><div class="copyline"><input id="ucV1611GoogleBusinessRedirect" readonly><button class="btn secondary small" type="button" onclick="copyValue('ucV1611GoogleBusinessRedirect')">Copy</button></div><div class="row"><div class="field"><label>Business Profile Account</label><select name="accountId"><option value="">Connect, then load accounts</option></select><input name="accountName" type="hidden"><small class="hint">The Google Business Profile account that owns/manages the location.</small></div><div class="field"><label>Business Location</label><select name="locationId"><option value="">Choose an account first</option></select><input name="locationName" type="hidden"><small class="hint">Select the exact verified location whose updates/reviews you want to manage.</small></div></div><div class="notice" data-v1645-gbp-access-note><strong>API access check:</strong> Connect Google OAuth, then use Load Accounts & Locations. If Google returns HTTP 429 and quota is 0, request Basic API Access for this same Cloud project.</div><div class="uc-v1611-business-state" data-v1611-business-state></div><div data-v1611-business-error></div><div class="uc-v1611-business-actions"><button class="btn secondary compact" type="submit">Save Settings</button><button class="btn compact" type="button" onclick="startUCV1611GoogleBusiness(this)">Connect Google Business Profile</button><button class="btn secondary compact" type="button" onclick="discoverUCV1611GoogleBusiness(this)">Load Accounts & Locations</button><button class="btn secondary compact" type="button" onclick="testUCV1611GoogleBusiness(this)">Test Connection</button><button class="btn secondary compact" type="button" onclick="disconnectUCV1611GoogleBusiness(this)">Disconnect</button></div></form>`;
    return d;
  }
  function ensureGoogleBusiness(){
    const panel=$('#socialMediaIntegrations');if(!panel)return null;let d=$('[data-social-card="googleBusiness"]',panel);if(!d)d=makeGoogleBusinessCard();
    const gi=$('[data-social-card="googleIndexing"]',panel),ix=$('[data-social-card="indexNow"]',panel);if(gi&&gi.nextElementSibling!==d)gi.insertAdjacentElement('afterend',d);else if(!gi&&ix&&d.nextElementSibling!==ix)panel.insertBefore(d,ix);else if(!gi&&!ix&&!d.parentElement)panel.appendChild(d);
    if(window.ucMakeInfoDetails&&!d.dataset.ucInfoFlip)window.ucMakeInfoDetails(d,GBP_HELP);return d;
  }
  function setBusinessSelect(select,items=[],selected='',placeholder='Choose one'){
    if(!select)return;const current=String(selected||'');select.innerHTML=`<option value="">${H(placeholder)}</option>`+(items||[]).map(x=>`<option value="${H(x.id)}" data-name="${H(x.name||'')}">${H(x.name||x.id)}${x.storeCode?` — ${H(x.storeCode)}`:''}</option>`).join('');select.value=current;if(current&&!select.value){const o=document.createElement('option');o.value=current;o.textContent=current;o.dataset.name='';select.appendChild(o);select.value=current;}
  }
  function bindBusinessSelectNames(form){
    const account=form?.elements?.accountId,locationSel=form?.elements?.locationId;if(account&&!account.dataset.v1611Bound){account.dataset.v1611Bound='1';account.addEventListener('change',async()=>{form.elements.accountName.value=account.selectedOptions[0]?.dataset?.name||account.selectedOptions[0]?.textContent||'';const chosen=account.value;if(!chosen){setBusinessSelect(locationSel,[],'','Choose business location');return;}const d=window.__ucV1611GbpDiscovery||{};if(String(d.selectedAccountId||'')===String(chosen)){loadDiscoveryLocations(form,chosen);return;}setBusinessSelect(locationSel,[],'','Loading business locations…');try{const r=await apiJson('/api/admin/google-business-auth',{method:'POST',body:JSON.stringify({action:'discover',accountId:chosen})});window.__ucV1611GbpDiscovery=r;loadDiscoveryLocations(form,chosen);window.ucSocialIntegrationResult?.('googleBusiness',r.message||`Google Business Profile loaded ${r.locations?.length||0} business location(s) for ${form.elements.accountName.value||'the selected account'}. Choose the correct location and save settings.`,'success');}catch(e){setBusinessSelect(locationSel,[],'','Could not load locations');window.ucSocialIntegrationResult?.('googleBusiness',e.message||'Google Business Profile locations could not be loaded. Confirm API access and that the connected Google account manages this Business Profile.','error');}});}
    if(locationSel&&!locationSel.dataset.v1611Bound){locationSel.dataset.v1611Bound='1';locationSel.addEventListener('change',()=>{form.elements.locationName.value=locationSel.selectedOptions[0]?.dataset?.name||locationSel.selectedOptions[0]?.textContent||'';});}
  }
  function loadDiscoveryLocations(form,accountId){
    const d=window.__ucV1611GbpDiscovery||{},saved=state().googleBusiness||{};let locations=(d.locations||[]);if(String(d.selectedAccountId||'')!==String(accountId||''))locations=[];setBusinessSelect(form.elements.locationId,locations,saved.locationId,'Choose business location');
  }
  function populateGoogleBusiness(){
    const d=ensureGoogleBusiness();if(!d)return;const form=$('form',d),g=state().googleBusiness||{};form.elements.enabled.checked=!!g.enabled;form.elements.autoPublish.checked=!!g.autoPublish;form.elements.clientId.value=g.clientId||'';form.elements.clientSecret.value='';form.elements.accountName.value=g.accountName||'';form.elements.locationName.value=g.locationName||'';$('#ucV1611GoogleBusinessSecretHint').textContent=g.clientSecretMasked?`Saved: ${g.clientSecretMasked}`:'No client secret saved yet.';$('#ucV1611GoogleBusinessRedirect').value=state().googleBusinessRedirectUrl||`${location.origin}/api/admin/google-business-oauth/callback`;
    const disc=window.__ucV1611GbpDiscovery||{};setBusinessSelect(form.elements.accountId,disc.accounts||[],g.accountId,'Connect, then load accounts');if(g.accountId)form.elements.accountId.value=g.accountId;setBusinessSelect(form.elements.locationId,(String(disc.selectedAccountId||'')===String(g.accountId||'')?disc.locations:[])||[],g.locationId,'Choose business location');
    const summary=$('summary',d);let badge=$('.uc-v168-status-badge',summary||d);if(summary&&!badge){badge=document.createElement('span');badge.className='uc-v168-status-badge';summary.appendChild(badge);}if(badge){badge.className='uc-v168-status-badge';if(g.connected){badge.textContent=g.apiAccessStatus==='ready'?'Ready':'OAuth connected';badge.classList.add('is-connected');badge.hidden=false;}else if(g.enabled){badge.textContent='Disconnected';badge.classList.add('is-disconnected');badge.hidden=false;}else{badge.textContent='';badge.hidden=true;}}
    const accessLabel=g.apiAccessStatus==='ready'?'Business Profile APIs: Ready':g.apiAccessStatus==='approval_required'?'Business Profile APIs: Project approval/quota required':g.apiAccessStatus==='account_discovery_ready'?'Account discovery API: Ready — select/save a location':g.apiAccessStatus==='oauth_connected'?'OAuth connected — API project access not checked yet':'API project access: Not checked';
    const note=$('[data-v1645-gbp-access-note]',d);if(note){note.innerHTML=g.apiAccessStatus==='approval_required'?`<strong>API access required:</strong> Google OAuth is connected, but this Cloud project returned HTTP 429. If Business Profile API quota is 0, request <strong>Basic API Access</strong> for this same project, then enable the Business Profile APIs and retry.`:`<strong>API access check:</strong> ${H(accessLabel)}. ${g.connected?'Use Load Accounts & Locations to verify Account Management + Business Information access.':'Connect Google OAuth first.'}`;}
    const st=$('[data-v1611-business-state]',d),er=$('[data-v1611-business-error]',d);if(st)st.innerHTML=g.connected?`<strong>Google OAuth connected</strong>${g.connectedEmail?` as ${H(g.connectedEmail)}`:''}<br><small>${H(accessLabel)}</small>${g.locationName?`<br><small>Selected location: ${H(g.locationName)}</small>`:''}${g.lastDiscoveryAt?`<br><small>Last account/location check: ${H(fmt(g.lastDiscoveryAt))}</small>`:''}${g.lastTestedAt?`<br><small>Last Posts/Reviews test: ${H(fmt(g.lastTestedAt))}</small>`:''}${g.lastPublishedAt?`<br><small>Last Business Profile post: ${H(fmt(g.lastPublishedAt))}</small>`:''}`:'<strong>Not connected.</strong> Save the OAuth Client ID/Secret, then connect Google Business Profile.';if(er)er.innerHTML='';bindBusinessSelectNames(form);
  }
  window.saveUCV1611GoogleBusiness=async function(e){
    e.preventDefault();const f=e.target,b=$('button[type="submit"]',f),old=b?.textContent,payload={platform:'google_business',...Object.fromEntries(new FormData(f).entries()),enabled:!!f.elements.enabled.checked,autoPublish:!!f.elements.autoPublish.checked};
    payload.accountName=f.elements.accountId.selectedOptions[0]?.dataset?.name||f.elements.accountName.value||'';payload.locationName=f.elements.locationId.selectedOptions[0]?.dataset?.name||f.elements.locationName.value||'';if(b){b.disabled=true;b.textContent='Saving…';}
    try{const r=await apiJson('/api/admin/social-integrations',{method:'POST',body:JSON.stringify(payload)});window.UCSocialIntegrations.settings=r.settings||{};window.ucSocialIntegrationResult?.('googleBusiness',r.message||'Google Business Profile settings were saved successfully. Run Test Connection before enabling automatic publication.','success');populateGoogleBusiness();}
    catch(err){window.ucSocialIntegrationResult?.('googleBusiness',err.message||'Google Business Profile settings could not be saved. Check the OAuth Client ID/Secret and selected account/location, then try again.','error');}
    finally{if(b){b.disabled=false;b.textContent=old||'Save Settings';}}
  };
  window.startUCV1611GoogleBusiness=async function(btn){const old=btn.textContent;btn.disabled=true;btn.textContent='Preparing…';try{const r=await apiJson('/api/admin/google-business-auth?action=url');window.ucSocialIntegrationResult?.('googleBusiness','Google Business Profile OAuth is ready to start. Google will now ask you to choose an account and approve Business Profile access.','success');location.href=r.url;}catch(e){window.ucSocialIntegrationResult?.('googleBusiness',e.message||'Google Business Profile OAuth could not start. Verify the OAuth Client ID/Secret and exact redirect URI, then try again.','error');btn.disabled=false;btn.textContent=old;}};
  window.discoverUCV1611GoogleBusiness=async function(btn){const old=btn.textContent;btn.disabled=true;btn.textContent='Loading…';try{const f=$('form',$('[data-social-card="googleBusiness"]')),requestedAccount=f?.elements?.accountId?.value||'';const r=await apiJson('/api/admin/google-business-auth',{method:'POST',body:JSON.stringify({action:'discover',accountId:requestedAccount})});window.__ucV1611GbpDiscovery=r;setBusinessSelect(f.elements.accountId,r.accounts||[],requestedAccount||state().googleBusiness?.accountId,'Choose Business Profile account');if(!f.elements.accountId.value&&r.selectedAccountId)f.elements.accountId.value=r.selectedAccountId;loadDiscoveryLocations(f,f.elements.accountId.value);f.elements.accountName.value=f.elements.accountId.selectedOptions[0]?.dataset?.name||'';window.ucSocialIntegrationResult?.('googleBusiness',r.message||`Google Business Profile account discovery succeeded. Loaded ${r.accounts?.length||0} account(s) and ${r.locations?.length||0} location(s). Choose the correct location and click Save Settings.`,'success');}catch(e){window.ucSocialIntegrationResult?.('googleBusiness',e.message||'Google Business Profile accounts/locations could not be loaded. If Google returned HTTP 429, check whether this Cloud project has Business Profile Basic API Access and a non-zero quota.','error');}finally{btn.disabled=false;btn.textContent=old;}};
  window.testUCV1611GoogleBusiness=async function(btn){const old=btn.textContent;btn.disabled=true;btn.textContent='Testing…';try{const r=await apiJson('/api/admin/google-business-auth',{method:'POST',body:JSON.stringify({action:'test'})});if(r.accounts)window.__ucV1611GbpDiscovery=r;window.ucSocialIntegrationResult?.('googleBusiness',r.message||'Google Business Profile authentication and API access are working.',r.ready===false?'notice':'success');await refreshSocialSettings(false);}catch(e){window.ucSocialIntegrationResult?.('googleBusiness',e.message||'Google Business Profile connection test failed. If HTTP 429 is shown, verify Basic API Access/quota for this Google Cloud project before changing OAuth credentials.','error');}finally{btn.disabled=false;btn.textContent=old;}};
  window.disconnectUCV1611GoogleBusiness=async function(btn){if(!confirm('Disconnect Google Business Profile? The OAuth app details and selected account/location will be kept for reconnection.'))return;const old=btn.textContent;btn.disabled=true;btn.textContent='Disconnecting…';try{const r=await apiJson('/api/admin/google-business-auth',{method:'POST',body:JSON.stringify({action:'disconnect'})});window.ucSocialIntegrationResult?.('googleBusiness',r.message||'Google Business Profile disconnected successfully. Automatic Business Profile posting and review sync are disabled until reconnection.','success');await refreshSocialSettings(false);}catch(e){window.ucSocialIntegrationResult?.('googleBusiness',e.message||'Google Business Profile could not be disconnected. Refresh and retry; the connection is kept unless the server confirms removal.','error');}finally{btn.disabled=false;btn.textContent=old;}};
  async function refreshSocialSettings(closeCards=false){try{const r=await apiJson('/api/admin/social-integrations');window.UCSocialIntegrations.settings=r.settings||{};augmentSocial();if(closeCards)$$('#socialMediaIntegrations details.uc-social-card').forEach(x=>x.open=false);return r;}catch(e){throw e;}}
