  function remaining(deadline,platform='instagram'){const ms=Date.parse(deadline||'')-Date.now();if(!Number.isFinite(ms)||ms<=0)return'DM window expired';const hours=Math.floor(ms/3600000),mins=Math.floor((ms%3600000)/60000),days=Math.floor(hours/24),h=hours%24,label=platform==='facebook'?'Facebook one-time DM':'Instagram initial DM';return days?`${days}d ${h}h ${mins}m remaining for ${label}`:`${h}h ${mins}m remaining for ${label}`;}
