    if(c.spam||spam)arr.push(actionButton('spam',spam?'Marked as spam':'Hide on the platform and mark as spam',spam?'':`ucV1611RemoteAction(${id},'spam')`,{active:spam,disabled:spam||deleted}));
    if(!resolved)arr.push(actionButton('resolve','Mark Resolved in this dashboard',`ucV1611RemoteAction(${id},'resolve')`,{disabled:deleted}));else arr.push(actionButton('resolve','Resolved — click to reopen',`ucV1611RemoteAction(${id},'reopen')`,{active:true,disabled:deleted}));
